impl CapabilityClient for ScimDirectoryClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            create_group: dependencies.one::<ScimDirectoryCreateGroup>()?,
            create_user: dependencies.one::<ScimDirectoryCreateUser>()?,
            delete_group: dependencies.one::<ScimDirectoryDeleteGroup>()?,
            delete_user: dependencies.one::<ScimDirectoryDeleteUser>()?,
            get_group: dependencies.one::<ScimDirectoryGetGroup>()?,
            get_user: dependencies.one::<ScimDirectoryGetUser>()?,
            list_groups: dependencies.one::<ScimDirectoryListGroups>()?,
            list_users: dependencies.one::<ScimDirectoryListUsers>()?,
            patch_group: dependencies.one::<ScimDirectoryPatchGroup>()?,
            patch_user: dependencies.one::<ScimDirectoryPatchUser>()?,
            repair_sync: dependencies.one::<ScimDirectoryRepairSync>()?,
            replace_group: dependencies.one::<ScimDirectoryReplaceGroup>()?,
            replace_user: dependencies.one::<ScimDirectoryReplaceUser>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for ScimDirectoryClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    create_group: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryCreateGroup>()?,
                    create_user: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryCreateUser>()?,
                    delete_group: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryDeleteGroup>()?,
                    delete_user: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryDeleteUser>()?,
                    get_group: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryGetGroup>()?,
                    get_user: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryGetUser>()?,
                    list_groups: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryListGroups>()?,
                    list_users: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryListUsers>()?,
                    patch_group: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryPatchGroup>()?,
                    patch_user: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryPatchUser>()?,
                    repair_sync: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryRepairSync>()?,
                    replace_group: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryReplaceGroup>()?,
                    replace_user: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ScimDirectoryReplaceUser>()?,
                    },
                ))
            })
            .collect()
    }
}

